const countPreviousRender=render;
let inventoryCounts=[],activeCount=null,countSequence=0;
function countEligible(){return boxes.filter(b=>b.qty>0&&!b.analysis&&!b.blocked&&!b.awaitingPacking&&mediumAssets.some(a=>a.id===b.id))}
function startInventoryCount(locationIndex){const loc=Number(locationIndex);if(!Number.isInteger(loc)||loc<0||loc>=locations.length)throw Error('Local inválido.');if(activeCount)throw Error('Já existe uma contagem em andamento. Continue ou cancele antes de iniciar outra.');activeCount={id:'INV-'+String(++countSequence).padStart(3,'0'),location:loc,startedAt:new Date().toISOString(),startedBy:'Operador demo',lines:[],status:'Em contagem'};inventoryCountPage()}
function addCountLine(rawId,rawQty){if(!activeCount)throw Error('Inicie uma contagem.');const id=assetIdKey(rawId);if(!id)throw Error('Informe o código da caixa.');if(activeCount.lines.some(l=>l.id===id))throw Error('Caixa já contada: '+id);const b=boxes.find(x=>x.id===id&&x.qty>0&&!x.analysis&&!x.blocked&&!x.awaitingPacking),qty=Number(rawQty);if(!b)throw Error('Caixa não encontrada no estoque disponível: '+id);if(!Number.isInteger(qty)||qty<0||qty>100)throw Error('Informe uma quantidade entre 0 e 100.');activeCount.lines.push({id,systemQty:b.qty,actualQty:qty,systemLocation:b.loc,flavor:b.flavor,grade:b.grade,state:b.state,lot:b.lot});return id}
function submitCountLine(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{addCountLine(d.id,d.qty);inventoryCountPage();toast('Caixa adicionada à contagem')}catch(err){$('count-error').textContent=err.message}}
function countComparison(c){const expected=countEligible().filter(b=>b.loc===c.location),seen=new Map(c.lines.map(l=>[l.id,l]));const lines=c.lines.map(l=>({...l,issue:l.systemLocation!==c.location?'Local divergente':l.actualQty!==l.systemQty?'Quantidade divergente':'Correto'}));for(const b of expected)if(!seen.has(b.id))lines.push({id:b.id,systemQty:b.qty,actualQty:null,systemLocation:b.loc,flavor:b.flavor,grade:b.grade,state:b.state,lot:b.lot,issue:'Não encontrado'});return lines}
function countDiscrepancies(c){return countComparison(c).filter(l=>l.issue!=='Correto')}
function finishInventoryCount(reason){if(!activeCount)throw Error('Nenhuma contagem em andamento.');const discrepancies=countDiscrepancies(activeCount),text=String(reason||'').trim();if(discrepancies.length&&!text)throw Error('Descreva o que foi verificado antes de enviar as divergências.');activeCount.completedAt=new Date().toISOString();activeCount.reason=text;activeCount.comparison=countComparison(activeCount);activeCount.status=discrepancies.length?'Aguardando aprovação':'Concluído sem divergências';inventoryCounts.unshift(activeCount);log(`${activeCount.id}: inventário de ${locations[activeCount.location]} concluído; ${discrepancies.length} divergências. ${text}`);const done=activeCount;activeCount=null;return done}
function finishCountForm(e){e.preventDefault();try{const c=finishInventoryCount(new FormData(e.target).get('reason'));view='Inventário físico';render();toast(c.status)}catch(err){$('count-finish-error').textContent=err.message}}
function cancelInventoryCount(){activeCount=null;view='Inventário físico';render();toast('Contagem cancelada')}
function inventoryCountPage(){view='Inventário físico';render();}
function countPageHTML(){if(!activeCount)return `<div class="heading"><div><div class="eyebrow">CONTAGEM FÍSICA</div><h1>Inventário</h1><p>Conte um local por vez e compare o físico com o sistema.</p></div></div><section class="panel"><h2>Iniciar uma contagem</h2><p>Escolha o local. O sistema cria uma fotografia do saldo esperado e aguarda os códigos encontrados.</p><form class="receipt-form" onsubmit="event.preventDefault();try{startInventoryCount(this.elements.location.value)}catch(err){$('count-start-error').textContent=err.message}">${select('location','Local a contar',locations,2)}<p id="count-start-error" class="receipt-error"></p><button class="primary" type="submit">Começar inventário</button></form></section>${countHistoryHTML()}`;
const c=activeCount,expected=countEligible().filter(b=>b.loc===c.location),comparison=countComparison(c),found=c.lines.length;return `<div class="heading"><div><div class="eyebrow">${esc(c.id)} · EM CONTAGEM</div><h1>${esc(locations[c.location])}</h1><p>Escaneie cada caixa encontrada e informe a quantidade real.</p></div><button onclick="cancelInventoryCount()">Cancelar</button></div><div class="stats"><div class="stat"><span>Esperadas</span><strong>${expected.length}</strong></div><div class="stat"><span>Escaneadas</span><strong>${found}</strong></div><div class="stat"><span>Sem divergência</span><strong>${comparison.filter(l=>l.issue==='Correto').length}</strong></div><div class="stat"><span>Para revisar</span><strong>${countDiscrepancies(c).length}</strong></div></div><div class="notice">Caixas completas começam com 100; caixas parciais e de separação devem ser contadas. Escanear uma caixa de outro local identifica uma divergência de localização.</div><form class="panel receipt-form" onsubmit="submitCountLine(event)"><h2>Adicionar caixa encontrada</h2><div class="receipt-grid"><label>ID / QR da caixa<input name="id" list="count-boxes" placeholder="MEDIA-001" required></label><label>Quantidade física<input name="qty" type="number" min="0" max="100" step="1" value="100" required></label></div><datalist id="count-boxes">${countEligible().filter(b=>!c.lines.some(l=>l.id===b.id)).map(b=>`<option value="${b.id}">${esc(b.flavor)} · sistema ${b.qty}</option>`).join('')}</datalist><p id="count-error" class="receipt-error"></p><button class="primary" type="submit">Adicionar à contagem</button></form><section class="work-panel"><div class="work-heading"><h2>Resultado provisório</h2><span class="count-pill">${comparison.length}</span></div>${comparison.map(l=>countLineHTML(l,c.location)).join('')||'<div class="queue-empty"><p>Escaneie a primeira caixa.</p></div>'}</section><form class="panel receipt-form" onsubmit="finishCountForm(event)"><h2>Finalizar contagem</h2><label>Observação da conferência<textarea name="reason" placeholder="Obrigatória quando houver divergências"></textarea></label><p>As divergências serão enviadas à Gestão. O saldo do sistema não será alterado agora.</p><p id="count-finish-error" class="receipt-error"></p><button class="primary" type="submit">Finalizar e enviar para aprovação</button></form>`}
function countLineHTML(l,countLoc){const actual=l.actualQty==null?'Não encontrada':l.actualQty+' pops',tone=l.issue==='Correto'?'ok':l.issue==='Não encontrado'?'danger':'warning';return `<div class="count-line"><div><strong>${l.id} · ${esc(l.flavor)}</strong><small>Sistema: ${l.systemQty} · ${esc(locations[l.systemLocation])} · físico: ${actual}</small></div><span class="count-status ${tone}">${l.issue}</span></div>`}
function countHistoryHTML(){return `<section class="panel"><h2>Contagens recentes</h2>${inventoryCounts.map(c=>`<div class="row"><div><strong>${c.id} · ${esc(locations[c.location])}</strong><small>${c.lines.length} caixas lidas · ${c.comparison?.filter(l=>l.issue!=='Correto').length||0} divergências</small></div><span class="tag ${c.status==='Aguardando aprovação'?'warning':'AAA'}">${c.status}</span></div>`).join('')||'<p>Nenhum inventário realizado nesta sessão.</p>'}</section>`}
function pendingApprovals(){return inventoryCounts.filter(c=>c.status==='Aguardando aprovação')}
function approvalHTML(){return `<section class="panel approval-panel"><div class="row"><div><h2>Aprovações de inventário</h2><p>Ajustes alteram o saldo somente após aprovação.</p></div><span class="count-pill">${pendingApprovals().length}</span></div>${pendingApprovals().map(c=>`<div class="row"><div><strong>${c.id} · ${esc(locations[c.location])}</strong><small>${countDiscrepancies(c).length} divergências · ${esc(c.reason)}</small></div><button class="primary" onclick="reviewCount('${c.id}')">Revisar</button></div>`).join('')||'<p>Nenhuma divergência aguardando aprovação.</p>'}</section>`}
function reviewCount(id){const c=inventoryCounts.find(c=>c.id===id);if(!c)return;view='Aprovação de inventário';render();$('app').innerHTML=`<div class="heading"><div><div class="eyebrow">GESTÃO · APROVAÇÃO</div><h1>${esc(c.id)} · ${esc(locations[c.location])}</h1><p>Revise todas as divergências antes de decidir.</p></div><button onclick="go('Inventário')">Voltar</button></div><section class="panel"><p><strong>Observação do operador:</strong> ${esc(c.reason)}</p>${countDiscrepancies(c).map(l=>countLineHTML(l,c.location)).join('')}</section><form class="panel receipt-form" onsubmit="decideCount(event,'${c.id}')"><label>Decisão<select name="decision"><option value="approve">Aprovar ajustes</option><option value="reject">Devolver para nova contagem</option></select></label><label>Comentário do responsável<textarea name="comment" required placeholder="Explique a decisão"></textarea></label><div class="notice">Ao aprovar: quantidades físicas substituem o saldo; caixas não encontradas ficam com saldo zero; caixas encontradas neste local são transferidas para ele. Um registro de ajuste será criado para cada diferença.</div><button class="primary" type="submit">Registrar decisão</button></form>`}
function decideCount(e,id){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{resolveCount(id,d.decision,d.comment);go('Inventário');toast(d.decision==='approve'?'Ajustes aprovados':'Contagem devolvida')}catch(err){toast(err.message)}}
function resolveCount(id,decision,comment){const c=inventoryCounts.find(c=>c.id===id);if(!c||c.status!=='Aguardando aprovação')throw Error('Contagem não está aguardando aprovação.');if(!String(comment||'').trim())throw Error('Informe um comentário.');if(decision==='reject'){c.status='Devolvido para nova contagem';c.review={decision,comment:comment.trim(),at:new Date().toISOString(),by:'Gestor demo'};log(`${id}: devolvido para nova contagem. ${comment.trim()}`);return c}if(decision!=='approve')throw Error('Decisão inválida.');const changes=[];for(const l of countDiscrepancies(c)){const b=boxes.find(b=>b.id===l.id);if(!b)continue;const before={qty:b.qty,loc:b.loc};if(l.actualQty==null)b.qty=0;else{b.qty=l.actualQty;b.loc=c.location}if(!b.qty)b.active=false;changes.push({boxId:b.id,before,after:{qty:b.qty,loc:b.loc},reason:l.issue})}const m={id:'MOV-'+String(warehouseMovements.length+1).padStart(3,'0'),type:'Ajuste de inventário aprovado',at:new Date().toISOString(),countId:id,approvedBy:'Gestor demo',comment:comment.trim(),changes};warehouseMovements.push(m);c.status='Aprovado e ajustado';c.review={decision,comment:comment.trim(),at:m.at,by:m.approvedBy,changes};log(`${id}: ${changes.length} ajustes aprovados por ${m.approvedBy}. ${comment.trim()}`);return c}
render=function(){countPreviousRender();if(view==='Inventário físico')$('app').innerHTML=countPageHTML();if(view==='Movimentar')$('app').insertAdjacentHTML('beforeend',`<section class="work-panel count-entry"><button class="task-row" onclick="inventoryCountPage()"><span class="task-icon">${icon('grid')}</span><span class="task-copy"><strong>Inventário</strong><small>Escanear e comparar o estoque físico</small></span><span class="task-status">Periódico</span>${icon('arrow')}</button></section>`);if(view==='Inventário'){$('app').insertAdjacentHTML('afterbegin',`<section class="inventory-management-strip"><div><strong>Contagem física</strong><span>${pendingApprovals().length?pendingApprovals().length+' aguardando aprovação':'Nenhuma aprovação pendente'}</span></div><button onclick="inventoryCountPage()">Nova contagem</button></section>`);$('app').insertAdjacentHTML('beforeend',approvalHTML()+countHistoryHTML())}if(view==='Movimentações')$('app').insertAdjacentHTML('beforeend',approvalHTML())};
render();

let orderRequests=[],orderRequestSequence=0,orderItemSequence=0;
const orderRequestTypes=["Venda","Evento","Amostra","Solicitação interna","Consignação / reposição","Empréstimo de equipamentos","Troca / devolução","Doação / patrocínio","Material promocional","Outro"];
function requestCatalog(){return productCatalog().map(function(p){return {code:p.code,name:p.name,unit:p.unit}}).concat([{code:"EQ-CARRINHO",name:"Carrinho de sorvete",unit:"un"},{code:"EQ-FREEZER",name:"Freezer",unit:"un"},{code:"EV-MESA",name:"Mesa",unit:"un"},{code:"EV-BANNER",name:"Banner",unit:"un"},{code:"EV-FLYER",name:"Flyer",unit:"un"},{code:"SERV-MONTAGEM",name:"Montagem / apoio operacional",unit:"serviço"},{code:"OUTRO",name:"Outro item",unit:"un"}])}
function requestItemHTML(n){return "<div class=\"request-item-row\" data-request-item=\""+n+"\"><label>Item<select name=\"item-"+n+"\">"+requestCatalog().map(function(p){return "<option value=\""+esc(p.code)+"\">"+esc(p.name)+" · "+esc(p.code)+"</option>"}).join("")+"</select></label><label>Quantidade<input name=\"qty-"+n+"\" type=\"number\" min=\"0.001\" step=\"0.001\" required value=\"1\"></label><label>Estado<select name=\"state-"+n+"\"><option>Não se aplica</option><option>Líquido</option><option>Congelado</option></select></label><button type=\"button\" class=\"request-remove\" aria-label=\"Remover item\" onclick=\"this.closest('[data-request-item]').remove()\">×</button></div>"}
function addRequestItem(){var n=++orderItemSequence;$("request-items").insertAdjacentHTML("beforeend",requestItemHTML(n));return n}
function ordersModuleHTML(){return "<div class=\"portal-shell\"><button class=\"module-back\" onclick=\"go('Início')\">"+icon("arrow")+"Todos os módulos</button><div class=\"portal-heading\"><div class=\"eyebrow\">PEDIDOS</div><h1>O que você precisa?</h1><p>Envie uma solicitação completa para a equipe de operações.</p></div><div class=\"module-grid\">"+portalCard("Novo pedido","Venda, evento, amostra, material, equipamento ou solicitação interna.","prepare","newOrderRequest()","Formulário único")+portalCard("Acompanhar pedidos","Veja o número e a situação das solicitações enviadas.","history","orderRequestListPage()",orderRequests.length+" pedidos")+"</div><div class=\"public-request-note\"><strong>Link externo previsto</strong><span>Quem estiver fora da empresa poderá preencher este mesmo formulário sem ver estoque, preços internos ou dados de outros pedidos.</span></div></div>"}
function newOrderRequest(){view="Novo pedido";render()}
function requestTypeOptions(){return orderRequestTypes.map(function(t){return "<option>"+esc(t)+"</option>"}).join("")}
function newOrderRequestHTML(){var today=new Date(),date=new Date(today.getTime()+86400000).toISOString().slice(0,10),n=++orderItemSequence;return "<div class=\"request-shell\"><button class=\"module-back\" onclick=\"go('Pedidos')\">"+icon("arrow")+"Pedidos</button><div class=\"request-heading\"><div><div class=\"eyebrow\">NOVA SOLICITAÇÃO</div><h1>Pedido para Operações</h1><p>Preencha o que precisa, onde e quando.</p></div><span class=\"request-step\">1 formulário</span></div><form id=\"request-form\" class=\"request-form\" onsubmit=\"submitOrderRequest(event)\"><section class=\"request-section\"><h2>1. Quem está pedindo</h2><div class=\"request-grid three\"><label>Seu nome<input name=\"requester\" required autocomplete=\"name\"></label><label>Telefone / WhatsApp<input name=\"contact\" required autocomplete=\"tel\"></label><label>Cliente, empresa ou área<input name=\"organization\" required></label></div></section><section class=\"request-section\"><h2>2. Motivo e prazo</h2><div class=\"request-grid three\"><label>Tipo de pedido<select name=\"type\" onchange=\"updateRequestForm()\">"+requestTypeOptions()+"</select></label><label>Precisamos entregar / retirar em<input name=\"neededDate\" type=\"date\" min=\""+date+"\" value=\""+date+"\" required></label><label>Horário desejado<input name=\"neededTime\" type=\"time\" required></label></div><div class=\"request-grid two\"><label>Como será atendido?<select name=\"fulfillment\" onchange=\"updateRequestForm()\"><option>Entrega YOLO</option><option>Retirada em YOLO</option><option>Uso dentro da YOLO</option><option>Transportadora / terceiro</option></select></label><label data-request-section=\"address\">Endereço completo<input name=\"address\" placeholder=\"Rua, número, complemento, cidade\"></label></div></section><section class=\"request-section request-conditional\" data-request-section=\"event\" hidden><h2>3. Dados do evento</h2><div class=\"request-grid three\"><label>Nome do evento<input name=\"eventName\"></label><label>Início<input name=\"eventStart\" type=\"datetime-local\"></label><label>Fim<input name=\"eventEnd\" type=\"datetime-local\"></label><label>Retirada / devolução prevista<input name=\"pickupAt\" type=\"datetime-local\"></label><label>Contato no local<input name=\"onsiteContact\"></label><label>Público estimado<input name=\"audience\" type=\"number\" min=\"0\" step=\"1\"></label></div><p class=\"field-help\">Após aprovação, o sistema verificará carrinhos, freezers e outros bens durante todo o período de entrega, evento, retirada e limpeza.</p></section><section class=\"request-section\"><h2><span data-step-items>3</span>. O que precisa ser separado</h2><div id=\"request-items\">"+requestItemHTML(n)+"</div><button type=\"button\" class=\"request-add\" onclick=\"addRequestItem()\">＋ Adicionar item</button><label>Instruções sobre sabores, materiais, montagem ou embalagem<textarea name=\"itemNotes\" placeholder=\"Ex.: sabores variados; 300 pops congelados; carrinho limpo e com guarda-sol\"></textarea></label></section><section class=\"request-section request-conditional\" data-request-section=\"return\" hidden><h2>Referência da troca ou devolução</h2><div class=\"request-grid two\"><label>Pedido / nota / evento de origem<input name=\"reference\"></label><label>O que deve voltar?<input name=\"returnDescription\"></label></div></section><section class=\"request-section\"><h2><span data-step-commercial>4</span>. Controle comercial</h2><div class=\"request-grid two\"><label>Será cobrado do cliente?<select name=\"billable\" onchange=\"updateRequestForm()\"><option value=\"yes\">Sim</option><option value=\"no\">Não</option><option value=\"review\">Precisa confirmar</option></select></label><label data-request-section=\"no-charge\" hidden>Motivo / centro de custo<input name=\"noChargeReason\" placeholder=\"Amostra, marketing, equipe, patrocínio...\"></label></div><label>Observações finais<textarea name=\"notes\" placeholder=\"Inclua tudo que a operação precisa saber para cumprir o pedido\"></textarea></label></section><div class=\"request-guardrail\"><strong>O envio ainda não reserva estoque ou equipamento.</strong><span>A equipe interna valida disponibilidade, prazo e cobrança antes de aprovar e iniciar a separação.</span></div><p id=\"request-error\" class=\"receipt-error\" role=\"alert\"></p><div class=\"request-actions\"><button type=\"button\" onclick=\"go('Pedidos')\">Cancelar</button><button class=\"primary\" type=\"submit\">Enviar para Operações</button></div></form></div>"}
function updateRequestForm(){var f=$("request-form");if(!f)return;var type=f.elements.type.value,event=type==="Evento",returns=type==="Troca / devolução",noCharge=["Amostra","Solicitação interna","Doação / patrocínio","Material promocional"].includes(type);f.querySelector('[data-request-section="event"]').hidden=!event;f.querySelector('[data-request-section="return"]').hidden=!returns;f.querySelector('[data-request-section="address"]').hidden=f.elements.fulfillment.value==="Uso dentro da YOLO";if(noCharge&&f.elements.billable.value==="yes")f.elements.billable.value="no";f.querySelector('[data-request-section="no-charge"]').hidden=f.elements.billable.value==="yes";f.querySelectorAll('[data-step-items]').forEach(function(e){e.textContent=event?"4":"3"});f.querySelectorAll('[data-step-commercial]').forEach(function(e){e.textContent=event?"5":"4"})}
function collectOrderRequest(form){var fd=new FormData(form),type=String(fd.get("type")||""),items=[].slice.call(form.querySelectorAll("[data-request-item]")).map(function(row){var n=row.dataset.requestItem,p=requestCatalog().find(function(x){return x.code===fd.get("item-"+n)}),qty=Number(fd.get("qty-"+n));if(!p||!Number.isFinite(qty)||qty<=0)throw Error("Revise os itens e as quantidades.");return {code:p.code,name:p.name,unit:p.unit,qty:qty,state:fd.get("state-"+n)}});if(!String(fd.get("requester")||"").trim()||!String(fd.get("contact")||"").trim()||!String(fd.get("organization")||"").trim())throw Error("Preencha seus dados de contato.");if(!orderRequestTypes.includes(type))throw Error("Escolha um tipo de pedido.");if(!fd.get("neededDate")||!fd.get("neededTime"))throw Error("Informe a data e o horário necessários.");if(!items.length)throw Error("Adicione pelo menos um item.");if(fd.get("fulfillment")!=="Uso dentro da YOLO"&&!String(fd.get("address")||"").trim())throw Error("Informe o endereço completo.");if(type==="Evento"&&(!fd.get("eventName")||!fd.get("eventStart")||!fd.get("eventEnd")||!fd.get("pickupAt")||!fd.get("onsiteContact")))throw Error("Complete os horários e o contato do evento.");if(type==="Troca / devolução"&&!String(fd.get("reference")||"").trim())throw Error("Informe o pedido, nota ou evento de origem.");if(fd.get("billable")!=="yes"&&!String(fd.get("noChargeReason")||"").trim())throw Error("Explique o motivo ou informe o centro de custo.");return {requester:String(fd.get("requester")).trim(),contact:String(fd.get("contact")).trim(),organization:String(fd.get("organization")).trim(),type:type,neededDate:fd.get("neededDate"),neededTime:fd.get("neededTime"),fulfillment:fd.get("fulfillment"),address:String(fd.get("address")||"").trim(),eventName:String(fd.get("eventName")||"").trim(),eventStart:fd.get("eventStart")||"",eventEnd:fd.get("eventEnd")||"",pickupAt:fd.get("pickupAt")||"",onsiteContact:String(fd.get("onsiteContact")||"").trim(),audience:Number(fd.get("audience")||0),items:items,itemNotes:String(fd.get("itemNotes")||"").trim(),reference:String(fd.get("reference")||"").trim(),returnDescription:String(fd.get("returnDescription")||"").trim(),billable:fd.get("billable"),noChargeReason:String(fd.get("noChargeReason")||"").trim(),notes:String(fd.get("notes")||"").trim()}}
function commitOrderRequest(data){var before=boxes.reduce(function(sum,b){return sum+b.qty},0),record=Object.assign({id:"PED-"+String(++orderRequestSequence).padStart(4,"0"),createdAt:new Date().toISOString(),status:"Enviado para análise"},data);orderRequests.unshift(record);var after=boxes.reduce(function(sum,b){return sum+b.qty},0);if(after!==before)throw Error("O pedido não pode alterar o estoque antes da aprovação.");log(record.id+": "+record.type+" enviado por "+record.requester+" para análise");return record}
function submitOrderRequest(e){e.preventDefault();try{var record=commitOrderRequest(collectOrderRequest(e.target));view="Pedido enviado";render();$("app").innerHTML=orderRequestSuccessHTML(record);toast("Pedido "+record.id+" enviado para Operações")}catch(err){$("request-error").textContent=err.message}}
function orderRequestSuccessHTML(r){return "<div class=\"request-shell request-success\"><span class=\"success-mark\">✓</span><div class=\"eyebrow\">SOLICITAÇÃO ENVIADA</div><h1>Pedido "+esc(r.id)+"</h1><p>A equipe de Operações recebeu sua solicitação.</p><div class=\"request-ticket\"><div><span>Tipo</span><strong>"+esc(r.type)+"</strong></div><div><span>Quando</span><strong>"+esc(r.neededDate)+" · "+esc(r.neededTime)+"</strong></div><div><span>Situação</span><strong>"+esc(r.status)+"</strong></div></div><div class=\"request-guardrail\"><strong>Próximo passo</strong><span>Operações verifica disponibilidade, cobrança e logística. Depois o pedido pode ser aprovado e programado para separação.</span></div><div class=\"request-actions center\"><button onclick=\"newOrderRequest()\">Fazer outro pedido</button><button class=\"primary\" onclick=\"orderRequestListPage()\">Acompanhar pedidos</button></div></div>"}
function orderRequestListPage(){view="Lista de pedidos";render()}
function orderListHTML(){return "<div class=\"request-shell\"><button class=\"module-back\" onclick=\"go('Pedidos')\">"+icon("arrow")+"Pedidos</button><div class=\"request-heading\"><div><div class=\"eyebrow\">ACOMPANHAMENTO</div><h1>Pedidos enviados</h1><p>Use o número do pedido para acompanhar com Operações.</p></div><button class=\"primary\" onclick=\"newOrderRequest()\">＋ Novo pedido</button></div><section class=\"request-list\">"+(orderRequests.length?orderRequests.map(function(r){return "<button class=\"request-list-row\" onclick=\"orderRequestDetail('"+r.id+"')\"><span><strong>"+esc(r.id)+" · "+esc(r.type)+"</strong><small>"+esc(r.organization)+" · "+r.items.length+" itens · "+esc(r.neededDate)+" às "+esc(r.neededTime)+"</small></span><span class=\"request-status\">"+esc(r.status)+"</span>"+icon("arrow")+"</button>"}).join(""):"<div class=\"queue-empty\"><p>Nenhum pedido enviado nesta sessão.</p><button class=\"primary\" onclick=\"newOrderRequest()\">Criar primeiro pedido</button></div>")+"</section></div>"}
function orderRequestDetail(id){var r=orderRequests.find(function(x){return x.id===id});if(!r)return;view="Detalhe do pedido";render();$("app").innerHTML="<div class=\"request-shell\"><button class=\"module-back\" onclick=\"orderRequestListPage()\">"+icon("arrow")+"Pedidos enviados</button><div class=\"request-heading\"><div><div class=\"eyebrow\">"+esc(r.status.toUpperCase())+"</div><h1>"+esc(r.id)+" · "+esc(r.type)+"</h1><p>"+esc(r.organization)+" · "+esc(r.requester)+"</p></div></div><section class=\"request-section request-detail\"><div class=\"request-ticket\"><div><span>Data necessária</span><strong>"+esc(r.neededDate)+" · "+esc(r.neededTime)+"</strong></div><div><span>Atendimento</span><strong>"+esc(r.fulfillment)+"</strong></div><div><span>Cobrança</span><strong>"+(r.billable==="yes"?"Cobrar cliente":r.billable==="no"?"Sem cobrança":"Confirmar")+"</strong></div></div><h2>Itens</h2>"+r.items.map(function(i){return "<div class=\"request-detail-row\"><strong>"+esc(i.name)+"</strong><span>"+i.qty+" "+esc(i.unit)+" · "+esc(i.state)+"</span></div>"}).join("")+"<h2>Entrega e observações</h2><p>"+esc(r.address||"Uso interno / retirada")+"</p><p>"+esc(r.itemNotes||r.notes||"Sem observações adicionais")+"</p></section></div>"}
