render=function(){ordersPreviousRender();if(interfaceMode!=="operations")return;if(view==="Pedidos")$("app").innerHTML=ordersModuleHTML();else if(view==="Novo pedido"){$("app").innerHTML=newOrderRequestHTML();updateRequestForm()}else if(view==="Lista de pedidos")$("app").innerHTML=orderListHTML()};
