document.head?.insertAdjacentHTML("beforeend","<style>body[data-interface=operations] aside{display:none}body[data-interface=operations] main{margin-left:0;padding-left:clamp(20px,5vw,72px);padding-right:clamp(20px,5vw,72px)}body[data-interface=operations] header{max-width:1320px;margin:auto}body[data-interface=operations] .mode-switch{display:none}.portal-shell{max-width:1080px;margin:0 auto}.portal-heading{padding:54px 0 28px}.portal-heading h1{font-size:34px}.module-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.module-card{min-height:210px;padding:26px;border-radius:18px;background:#fff;text-align:left;display:flex;flex-direction:column;align-items:stretch;border:1px solid var(--line);box-shadow:0 5px 20px #1b384708}.module-card:hover{background:#fff;border-color:#75aa89;box-shadow:0 12px 34px #1b384710}.module-card .action-icon{margin-bottom:26px}.module-card strong{font-size:22px}.module-card small{font-size:14px;color:#748294;font-weight:400;margin-top:8px}.module-card .module-foot{display:flex;justify-content:space-between;align-items:center;margin-top:auto;padding-top:20px;color:#376048;font-size:13px}.operations-action-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.module-back{margin-top:24px;background:transparent;border:0;padding-left:0;color:#496c58}.module-back svg{vertical-align:middle;margin-right:6px;transform:rotate(180deg)}@media(max-width:1050px){.operations-action-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){body[data-interface=operations] main{padding-bottom:40px}.module-grid,.operations-action-grid{grid-template-columns:1fr}.portal-heading{padding-top:28px}.module-card{min-height:170px}body[data-interface=operations] header{height:68px}.workspace-crumb>span:last-child{font-size:0}.workspace-crumb>span:last-child:after{content:'YOLO OS';font-size:13px}}</style>");
function portalCard(title,description,symbol,action,status){
  return "<button class=\"module-card\" onclick=\""+action+"\"><span class=\"action-icon "+symbol+"\">"+icon(symbol)+"</span><strong>"+title+"</strong><small>"+description+"</small><span class=\"module-foot\"><span>"+status+"</span>"+icon("arrow")+"</span></button>";
}
function portalHTML(){
  return "<div class=\"portal-shell\"><div class=\"portal-heading\"><div class=\"eyebrow\">YOLO OS</div><h1>Olá, Operador.</h1><p>Escolha onde você quer trabalhar.</p></div><div class=\"module-grid\">"
    +portalCard("Operações","Receber, preparar, movimentar e inventariar.","grid","go('Operações')","4 ações")
    +portalCard("Pedidos","Solicitações de vendas, amostras e retiradas.","prepare","go('Pedidos')","Próxima etapa")
    +portalCard("Financeiro","Faturamento, recebimentos e pendências.","history","go('Financeiro')","Próxima etapa")
    +portalCard("Gestão","Estoque, documentos, cadastros e aprovações.","inventory","switchInterface('management')","Visão completa")
    +"</div></div>";
}
function operationsModuleHTML(){
  return "<div class=\"portal-shell\"><button class=\"module-back\" onclick=\"go('Início')\">"+icon("arrow")+"Todos os módulos</button><div class=\"portal-heading\"><div class=\"eyebrow\">OPERAÇÕES</div><h1>O que vamos fazer?</h1><p>Escolha uma ação operacional.</p></div><div class=\"action-grid operations-action-grid\">"
    +actionCard("Receber","Registrar produtos, nota fiscal e caixas de entrada.","receive","receive()","01")
    +actionCard("Preparar","Conferir, classificar e encaixotar os produtos.","prepare","go('Preparar')","02")
    +actionCard("Movimentar","Transferir caixas e separar produtos para saída.","move","go('Movimentar')","03")
    +actionCard("Inventariar","Escanear o estoque físico e enviar diferenças para aprovação.","inventory","inventoryCountPage()","04")
    +"</div></div>";
}
function futureModuleHTML(name){
  const pedidos=name==="Pedidos";
  return "<div class=\"portal-shell\"><button class=\"module-back\" onclick=\"go('Início')\">"+icon("arrow")+"Todos os módulos</button><div class=\"portal-heading\"><div class=\"eyebrow\">"+name.toUpperCase()+"</div><h1>"+name+"</h1><p>Este módulo será a próxima etapa do protótipo.</p></div><div class=\"module-grid\">"
    +portalCard(pedidos?"Novo pedido":"Faturamento",pedidos?"Vendas, amostras, solicitações e eventos.":"Entregas aguardando emissão no Bling.","prepare","toast('Disponível na próxima etapa')","Em breve")
    +portalCard(pedidos?"Acompanhar pedidos":"Recebimentos",pedidos?"Aprovação, separação, entrega e retirada.":"Pagamentos, atrasos e conciliação.","history","toast('Disponível na próxima etapa')","Em breve")
    +"</div></div>";
}
const touchHubPreviousRender=render;
render=function(){
  touchHubPreviousRender();
  if(interfaceMode!=="operations") return;
  if(view==="Início") $("app").innerHTML=portalHTML();
  else if(view==="Operações") $("app").innerHTML=operationsModuleHTML();
  else if(view==="Pedidos"||view==="Financeiro") $("app").innerHTML=futureModuleHTML(view);
  else if(["Recebimento","Preparar","Conferência","Encaixotamento","Etiquetas","Movimentar","Transferir caixas","Separação","Inventário físico"].includes(view)){
    $("app").insertAdjacentHTML("afterbegin","<button class=\"module-back\" onclick=\"go('Operações')\">"+icon("arrow")+"Operações</button>");
  }
};
view="Início";
render();

