function saveSeparationJob(e,printAfter){e.preventDefault();var f=$("separation-form"),fd=new FormData(f),id=f.querySelector(".sheet-id strong").textContent,j=separationJobs.find(function(x){return x.id===id});try{var delivery=String(fd.get("deliveryDriver")||""),pickup=String(fd.get("pickupDriver")||"");if(!delivery)throw Error("Defina o motorista da entrega.");if(j.items.some(function(i){return i.returnable})&&!pickup)throw Error("Defina o motorista da retirada.");Object.assign(j,{deliveryDriver:delivery,pickupDriver:pickup,vehicle:String(fd.get("vehicle")||"").trim(),stage:fd.get("stage"),departureAt:fd.get("departureAt")||"",returnAt:fd.get("returnAt")||"",operationsNotes:String(fd.get("operationsNotes")||"").trim(),checked:fd.getAll("checkedItems").map(String)});log(j.id+": ordem operacional atualizada; entrega "+delivery+"; retirada "+pickup);toast("Ordem salva");if(printAfter){$("print-date").textContent=new Date().toLocaleDateString("pt-BR");window.print()}else separationBoard()}catch(err){$("separation-error").textContent=err.message}}
