function syncRequestFromSeparation(j){var r=orderRequests.find(function(x){return x.id===j.id});if(!r)return null;Object.assign(r,{status:j.stage,operationalStage:j.stage,deliveryDriver:j.deliveryDriver,pickupDriver:j.pickupDriver,vehicle:j.vehicle,departureAt:j.departureAt||"",returnAt:j.returnAt||"",separationChecked:j.checked.slice(),separationTotal:j.items.length});return r}
function trackedOrders(){syncSeparationJobs();separationJobs.forEach(syncRequestFromSeparation);return separationJobs.map(function(j){var r=orderRequests.find(function(x){return x.id===j.id});return {id:j.id,type:j.type,organization:j.client,recipient:j.recipient,recipientContact:j.recipientContact,address:j.address,neededDate:j.deliveryDate,neededTime:j.deliveryWindow,status:j.stage,deliveryDriver:j.deliveryDriver,pickupDriver:j.pickupDriver,vehicle:j.vehicle,departureAt:j.departureAt||"",returnAt:j.returnAt||j.pickupAt||"",items:j.items,checked:j.checked,eventStart:j.eventStart,eventEnd:j.eventEnd,pickupAt:j.pickupAt,operationsNotes:j.operationsNotes,request:r||null}})}
const synchronizedCommitOrderRequest=commitOrderRequest;
commitOrderRequest=function(data){var r=synchronizedCommitOrderRequest(data);syncSeparationJobs();var j=separationJobs.find(function(x){return x.id===r.id});if(j)syncRequestFromSeparation(j);return r};
const synchronizedSaveSeparationJob=saveSeparationJob;
saveSeparationJob=function(e,printAfter){var f=$("separation-form"),id=f&&f.querySelector(".sheet-id strong")?f.querySelector(".sheet-id strong").textContent:"";synchronizedSaveSeparationJob(e,printAfter);var j=separationJobs.find(function(x){return x.id===id});if(j)syncRequestFromSeparation(j)};
const synchronizedOrdersModuleHTML=ordersModuleHTML;
ordersModuleHTML=function(){var count=trackedOrders().length;return synchronizedOrdersModuleHTML().replace(orderRequests.length+" pedidos",count+" pedidos")};
orderListHTML=function(){var tracked=trackedOrders();return "<div class=\"request-shell\"><button class=\"module-back\" onclick=\"go('Pedidos')\">"+icon("arrow")+"Pedidos</button><div class=\"request-heading\"><div><div class=\"eyebrow\">ACOMPANHAMENTO</div><h1>Pedidos</h1><p>A mesma ordem acompanha solicitação, separação, entrega e retorno.</p></div><button class=\"primary\" onclick=\"newOrderRequest()\">＋ Novo pedido</button></div><section class=\"request-list\">"+(tracked.length?tracked.map(function(r){var progress=r.checked.length+"/"+r.items.length,drivers=[r.deliveryDriver?"Entrega: "+r.deliveryDriver:"Entrega pendente",r.items.some(function(i){return i.returnable})?(r.pickupDriver?"Retirada: "+r.pickupDriver:"Retirada pendente"):"Sem retirada"].join(" · ");return "<button class=\"request-list-row synchronized-row\" onclick=\"orderRequestDetail('"+r.id+"')\"><span><strong>"+esc(r.id)+" · "+esc(r.type)+" · "+esc(r.organization)+"</strong><small>"+esc(r.neededDate)+" · "+esc(r.neededTime)+" · "+progress+" separados</small><small>"+esc(drivers)+"</small></span><span class=\"request-status stage-"+esc(separationStageTone(r.status))+"\">"+esc(r.status)+"</span>"+icon("arrow")+"</button>"}).join(""):"<div class=\"queue-empty\"><p>Nenhum pedido aberto.</p><button class=\"primary\" onclick=\"newOrderRequest()\">Criar primeiro pedido</button></div>")+"</section></div>"};
function trackingTimelineHTML(stage){var index=separationStages.indexOf(stage);return "<div class=\"tracking-timeline\">"+separationStages.map(function(s,i){return "<span class=\""+(i<index?"done":i===index?"current":"")+"\"><i>"+(i<index?"✓":i+1)+"</i><strong>"+esc(s)+"</strong></span>"}).join("")+"</div>"}
orderRequestDetail=function(id){var r=trackedOrders().find(function(x){return x.id===id});if(!r)return;view="Detalhe do pedido";render();var returns=r.items.filter(function(i){return i.returnable});$("app").innerHTML="<div class=\"request-shell\"><button class=\"module-back\" onclick=\"orderRequestListPage()\">"+icon("arrow")+"Acompanhar pedidos</button><div class=\"request-heading\"><div><div class=\"eyebrow\">PEDIDO SINCRONIZADO</div><h1>"+esc(r.id)+" · "+esc(r.type)+"</h1><p>"+esc(r.organization)+" · entrega para "+esc(r.recipient)+"</p></div><span class=\"request-status stage-"+esc(separationStageTone(r.status))+"\">"+esc(r.status)+"</span></div>"+trackingTimelineHTML(r.status)+"<section class=\"request-section tracking-summary\"><div class=\"request-ticket\"><div><span>Entrega</span><strong>"+esc(r.neededDate)+" · "+esc(r.neededTime)+"</strong></div><div><span>Motorista</span><strong>"+esc(r.deliveryDriver||"Ainda não definido")+"</strong></div><div><span>Separação</span><strong>"+r.checked.length+" de "+r.items.length+" itens</strong></div></div><div class=\"tracking-grid\"><div><span>Destino</span><strong>"+esc(r.address)+"</strong></div><div><span>Contato</span><strong>"+esc(r.recipient)+" · "+esc(r.recipientContact)+"</strong></div><div><span>Retirada</span><strong>"+(returns.length?esc(r.pickupDriver||"Motorista ainda não definido")+(r.returnAt?" · "+esc(friendlyDateTime(r.returnAt)):""):"Não se aplica")+"</strong></div><div><span>Veículo</span><strong>"+esc(r.vehicle||"Ainda não definido")+"</strong></div></div><h2>Itens do pedido</h2>"+r.items.map(function(i){return "<div class=\"request-detail-row\"><strong>"+(r.checked.includes(i.code)?"✓ ":"□ ")+esc(i.name)+"</strong><span>"+i.qty+" "+esc(i.unit)+(i.state?" · "+esc(i.state):"")+"</span></div>"}).join("")+"<p class=\"sync-note\">As atribuições e o progresso são atualizados a partir do painel Separação.</p></section></div>"};
document.head?.insertAdjacentHTML("beforeend","<style>.synchronized-row{grid-template-columns:1fr auto 24px}.synchronized-row>span:first-child{gap:2px}.request-status.stage-working{background:#fff0c9;color:#6d5008}.request-status.stage-route{background:#e2eef9;color:#245982}.request-status.stage-return{background:#eee6f5;color:#684688}.tracking-timeline{display:grid;grid-template-columns:repeat(4,1fr);margin-bottom:14px;background:#fff;border:1px solid var(--line);border-radius:11px;overflow:hidden}.tracking-timeline span{display:flex;align-items:center;gap:8px;padding:12px;border-right:1px solid var(--line);color:#89938e}.tracking-timeline span:last-child{border-right:0}.tracking-timeline i{display:grid;place-items:center;width:23px;height:23px;border-radius:50%;background:#e9eeeb;font-style:normal;font-size:11px}.tracking-timeline strong{font-size:12px}.tracking-timeline .done{color:#35674e}.tracking-timeline .done i{background:#d7eadf}.tracking-timeline .current{color:#153d2b;background:#edf6f1}.tracking-timeline .current i{background:#176f45;color:#fff}.tracking-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1px;margin-bottom:20px;background:var(--line);border:1px solid var(--line);border-radius:9px;overflow:hidden}.tracking-grid>div{display:grid;gap:4px;padding:12px;background:#fff}.tracking-grid span{font-size:11px;color:#708077}.tracking-grid strong{font-size:13px}.sync-note{margin-top:15px;padding:10px;background:#edf6f1;border-radius:7px;color:#315e47;font-size:12px}@media(max-width:700px){.tracking-timeline{grid-template-columns:1fr 1fr}.tracking-timeline span{border-bottom:1px solid var(--line)}.tracking-grid{grid-template-columns:1fr}.synchronized-row{grid-template-columns:1fr auto}.synchronized-row svg{display:none}}</style>");
